function Footer() {
  return <footer className="bg-[#143c4e] px-5 py-12 text-[#e7f0ee]">
    <div className="mx-auto grid max-w-[1160px] gap-8 md:grid-cols-[1.5fr_1fr_1fr]">
      <div><div className="text-lg font-bold tracking-wide">THE PULP DOCTOR</div><p className="mt-2 max-w-sm text-sm leading-6 text-[#bcd0d1]">Specialist endodontic care with time to listen, explain and plan.</p><p className="mt-5 text-sm text-[#bcd0d1]">Dr Charu Makhija · Restorative Dentist and Endodontist</p></div>
      <div><p className="eyebrow !text-[#8fc5bd]">Explore</p><div className="mt-4 grid gap-3 text-sm"><a href="/#about">About Dr Makhija</a><a href="/#care">Treatments</a><Link href="/refer-a-patient">Refer a patient</Link><a href="/#book">Appointments</a></div></div>
      <div><p className="eyebrow !text-[#8fc5bd]">Contact</p><p className="mt-4 text-sm leading-6 text-[#d4e0df]">For clinic details and appointment availability, please select a location below.</p><Link href="/admin/login" className="mt-4 inline-block text-xs text-[#9fb8bb]">Administrator sign in</Link></div>
    </div><div className="mx-auto mt-9 max-w-[1160px] border-t border-white/15 pt-5 text-xs text-[#a9c0c1]">© {new Date().getFullYear()} The Pulp Doctor. Privacy and consent information should be confirmed by the practice.</div>
  </footer>;
}
function Shell({children}:{children:React.ReactNode}) { return <div className="site-shell min-h-[100dvh]"><Header/>{children}<Footer/></div>; }

function LocationCards({locations,loading,error,retry}:{locations:ClinicLocation[];loading:boolean;error:boolean;retry:()=>void}) {
  if (loading) return <div className="grid gap-4 md:grid-cols-3">{[0,1,2].map(i=><div key={i} className="h-48 animate-pulse rounded-2xl bg-[#e6eff0]"/> )}</div>;
  if (error) return <div className="rounded-2xl border border-[#d1e0e1] bg-white p-6 text-sm"><p>Clinic details are temporarily unavailable.</p><button className="mt-3 font-bold text-[#176d70]" onClick={retry}>Try again</button></div>;
  if (!locations.length) return <p className="rounded-xl bg-white p-5 text-sm text-[#55707a]">Clinic locations will appear when the practice schedule is available.</p>;
  return <div className="grid gap-4 md:grid-cols-3">{locations.map(location=><article key={location.id} className="soft-card rounded-2xl p-6">
    <div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e7f2f1] text-[#267c79]"><MapPin size={19}/></span><a className="text-xs font-bold text-[#277a78] underline underline-offset-4" href={location.mapsUrl} target="_blank" rel="noreferrer">Directions</a></div>
    <h3 className="mt-5 text-xl font-bold text-[#183e50]">{location.name}</h3><p className="mt-1 text-sm font-medium text-[#53717a]">{location.clinicName}</p>
    <p className="mt-4 text-sm leading-6 text-[#617680]">{location.address}</p>
    <div className="mt-5 border-t border-[#e4eded] pt-4"><p className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-[#417c7c]"><Clock3 size={14}/> Weekly hours</p>
      {location.weeklyHours.length ? location.weeklyHours.map(item=><p key={item.day} className="mt-2 flex justify-between text-sm text-[#48616d]"><span>{['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][item.day]}</span><span>{item.opensAt}–{item.closesAt}</span></p>) : <p className="mt-2 text-sm text-[#687e85]">Hours are not currently published.</p>}
    </div></article>)}</div>;
}
function Booking({locations}:{locations:ClinicLocation[]}) {
  const [locationId,setLocationId]=useState(''); const [date,setDate]=useState(today()); const [slotId,setSlotId]=useState('');
  const [name,setName]=useState(''); const [phone,setPhone]=useState(''); const [email,setEmail]=useState(''); const [kind,setKind]=useState(''); const [notes,setNotes]=useState('');
  const [confirmation,setConfirmation]=useState<{id:string;reference:string;time:string;date:string;status:string;managementToken:string}|null>(null);
  const params=useMemo(()=>({locationId,date}),[locationId,date]);
  const availability=useGetAvailability(params,{query:{enabled:!!locationId&&!!date,queryKey:getGetAvailabilityQueryKey(params)}});
  const create=useCreateAppointment(); const cancel=useCancelAppointment(); const reschedule=useRescheduleAppointment(); const [manageId,setManageId]=useState(''); const [token,setToken]=useState(''); const [manageMessage,setManageMessage]=useState('');
  const [manageLocation,setManageLocation]=useState(''); const [manageDate,setManageDate]=useState(today()); const [manageSlot,setManageSlot]=useState('');
  const manageParams=useMemo(()=>({locationId:manageLocation,date:manageDate}),[manageLocation,manageDate]);
  const manageAvailability=useGetAvailability(manageParams,{query:{enabled:!!manageLocation&&!!manageDate,queryKey:getGetAvailabilityQueryKey(manageParams)}});
  const validSlots=availability.data?.slots.filter(slot=>slot.available) ?? [];
  function submit(e:React.FormEvent) {e.preventDefault(); if(!locationId||!slotId)return; create.mutate({data:{locationId,date,slotId,patientName:name,phone,email,appointmentType:kind,notes}}, {onSuccess:(result)=>setConfirmation({id:result.id,reference:result.reference,time:result.time,date:result.date,status:result.status,managementToken:result.managementToken})});}
  return <section id="book" className="section-pad bg-[#edf5f5]">
    <div className="mx-auto grid max-w-[1160px] gap-10 lg:grid-cols-[.85fr_1.15fr]">
      <div className="pt-4"><p className="eyebrow">Appointment request</p><h2 className="serif mt-4 text-5xl leading-[.98] text-[#193f51]">A clear next step,<br/>at your pace.</h2>
        <p className="mt-5 max-w-md leading-7 text-[#54707a]">Choose a clinic and a published time. Your appointment is confirmed only after the practice has received your request.</p>
        <div className="mt-8 rounded-2xl border border-[#cfe1e2] bg-white/70 p-5"><p className="flex items-center gap-2 font-bold text-[#245366]"><ShieldCheck size={17}/> Your details stay private</p><p className="mt-2 text-sm leading-6 text-[#617981]">We only show available times. No other patient details are displayed.</p></div>
      </div>
      <div className="soft-card rounded-[1.5rem] p-5 sm:p-8">
      {confirmation ? <div className="py-8 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-[#e2f2ee] text-[#24766d]"><Check size={26}/></span><p className="eyebrow mt-5">Request received</p><h3 className="serif mt-2 text-4xl text-[#173f51]">{confirmation.status==='confirmed'?'Appointment confirmed':'Appointment request received'}</h3><p className="mt-4 text-[#526d77]">Reference <strong>{confirmation.reference}</strong></p><p className="mt-2 text-sm">{dateLabel(confirmation.date)} · {confirmation.time}</p><div className="mx-auto mt-6 max-w-md rounded-xl border border-[#d8e7e6] bg-[#f5f9f8] p-4 text-left"><p className="text-xs font-bold uppercase tracking-wider text-[#54757a]">Private management details</p><p className="mt-2 text-xs text-[#60767d]">Save these securely. They are needed to change or cancel your appointment and will not appear in the URL.</p><p className="mt-3 break-all text-xs text-[#294e5d]">Appointment ID: {confirmation.id}</p><p className="mt-2 break-all font-mono text-xs text-[#294e5d]">Management token: {confirmation.managementToken}</p><button className="mt-3 text-xs font-bold text-[#267b75] underline" type="button" onClick={()=>{setManageId(confirmation.id);setToken(confirmation.managementToken);setManageMessage('Private management details loaded below.')}}>Use these details to manage appointment</button></div></div> :
      <form className="space-y-5" onSubmit={submit}>
        <div className="grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold text-[#284b5b]">Clinic location<select required className="field mt-2" value={locationId} onChange={e=>{setLocationId(e.target.value);setSlotId('')}}><option value="">Choose a clinic</option>{locations.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></label><label className="text-sm font-semibold text-[#284b5b]">Preferred date<input className="field mt-2" type="date" min={today()} required value={date} onChange={e=>{setDate(e.target.value);setSlotId('')}}/></label></div>
        <div><div className="mb-2 flex items-center justify-between"><label className="text-sm font-semibold text-[#284b5b]">Available appointment times</label>{availability.isFetching&&<span className="text-xs text-[#638088]">Checking live availability…</span>}</div>
          {!locationId ? <p className="rounded-xl bg-[#f1f6f6] p-4 text-sm text-[#6b8188]">Select a location to see its published availability.</p> : availability.isError ? <div className="rounded-xl border border-[#e6c7c1] bg-[#fcf5f3] p-4 text-sm text-[#7a453a]"><p>Availability could not be loaded. Your form details are saved.</p><button type="button" onClick={()=>availability.refetch()} className="mt-2 font-bold underline">Retry</button></div> : availability.data&&!availability.data.bookingEnabled ? <p className="rounded-xl bg-[#f1f6f6] p-4 text-sm text-[#6b8188]">{availability.data.unavailableReason||'Online booking is not available for this date.'}</p> : validSlots.length ? <div className="flex flex-wrap gap-2">{validSlots.map(slot=><button type="button" key={slot.id} onClick={()=>setSlotId(slot.id)} aria-pressed={slotId===slot.id} className={`rounded-full border px-4 py-2 text-sm font-semibold ${slotId===slot.id?'border-[#176d70] bg-[#176d70] text-white':'border-[#c9dadd] bg-white text-[#315767] hover:border-[#3f9088]'}`}>{slot.label}{slot.emergency?' · Emergency':''}</button>)}</div> : locationId&&availability.data&&<p className="rounded-xl bg-[#f1f6f6] p-4 text-sm text-[#6b8188]">No published appointments are available on this date.</p>}
        </div>
        <div className="grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold text-[#284b5b]">Patient name<input className="field mt-2" required minLength={2} maxLength={120} autoComplete="name" value={name} onChange={e=>setName(e.target.value)}/></label><label className="text-sm font-semibold text-[#284b5b]">Phone<input className="field mt-2" required minLength={8} maxLength={24} autoComplete="tel" value={phone} onChange={e=>setPhone(e.target.value)}/></label></div>
        <div className="grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold text-[#284b5b]">Email<input className="field mt-2" type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="text-sm font-semibold text-[#284b5b]">Appointment type<input className="field mt-2" required minLength={2} maxLength={80} value={kind} onChange={e=>setKind(e.target.value)} placeholder="Please describe what you need"/></label></div>
        <label className="block text-sm font-semibold text-[#284b5b]">Notes <span className="font-normal text-[#71858b]">(optional)</span><textarea className="field mt-2 min-h-20" maxLength={1500} value={notes} onChange={e=>setNotes(e.target.value)}/></label>
        {create.isError&&<p role="alert" className="rounded-lg bg-[#fcf1ee] p-3 text-sm text-[#934a3f]">{errorText(create.error)} No appointment has been confirmed. Please retry.</p>}
        <button className="btn-primary w-full disabled:cursor-not-allowed disabled:opacity-50" type="submit" disabled={!slotId||create.isPending}>{create.isPending?'Sending request…':'Review and request appointment'} <ArrowRight size={16}/></button>
        <p className="text-center text-xs text-[#70858b]">A booking is final only when the server confirms it.</p>
      </form>}
      <details className="mt-6 border-t border-[#e3eded] pt-4"><summary className="flex cursor-pointer list-none items-center gap-2 text-sm font-bold text-[#365b69]"><ClipboardList size={16}/> Manage an existing appointment</summary>
        <div className="mt-4 grid gap-3 sm:grid-cols-2"><input className="field" aria-label="Appointment reference" placeholder="Appointment reference" value={manageId} onChange={e=>setManageId(e.target.value)}/><input className="field" aria-label="Management token" placeholder="Private management token" value={token} onChange={e=>setToken(e.target.value)}/></div>
        <div className="mt-3 grid gap-3 sm:grid-cols-3"><select className="field" aria-label="New clinic location" value={manageLocation} onChange={e=>{setManageLocation(e.target.value);setManageSlot('')}}><option value="">New clinic</option>{locations.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select><input className="field" aria-label="New appointment date" type="date" min={today()} value={manageDate} onChange={e=>{setManageDate(e.target.value);setManageSlot('')}}/><select className="field" aria-label="New appointment time" value={manageSlot} onChange={e=>setManageSlot(e.target.value)}><option value="">Available time</option>{manageAvailability.data?.slots.filter(s=>s.available).map(s=><option key={s.id} value={s.id}>{s.label}</option>)}</select></div>
        {manageAvailability.isError&&manageLocation&&<p className="mt-2 text-xs text-[#925044]">Times unavailable. Retry availability before rescheduling.</p>}
        <div className="mt-3 flex flex-wrap gap-2"><button className="btn-outline !py-2 text-sm" type="button" disabled={cancel.isPending||manageId.length===0||token.length<20} onClick={()=>{if(confirm('Cancel this appointment?'))cancel.mutate({appointmentId:manageId,data:{managementToken:token}}, {onSuccess:()=>setManageMessage('The server has cancelled this appointment.'),onError:e=>setManageMessage(errorText(e))})}}>Cancel appointment</button><button className="btn-outline !py-2 text-sm" type="button" disabled={reschedule.isPending||!manageId||token.length<20||!manageLocation||!manageSlot} onClick={()=>{if(confirm('Reschedule this appointment to the selected published slot?'))reschedule.mutate({appointmentId:manageId,data:{managementToken:token,locationId:manageLocation,date:manageDate,slotId:manageSlot}},{onSuccess:()=>setManageMessage('The server has rescheduled this appointment.'),onError:e=>setManageMessage(errorText(e))})}}>{reschedule.isPending?'Rescheduling…':'Reschedule appointment'}</button></div>
        {(manageMessage||cancel.isError||reschedule.isError)&&<p role="status" className="mt-2 text-sm text-[#775147]">{manageMessage||errorText(cancel.error||reschedule.error)}</p>}
      </details></div>
    </div>
  </section>;
}

function HomePage() {
  const health=useHealthCheck(); const locationsQuery=useListLocations(); const locations=locationsQuery.data??[];
  return <Shell><main>
    <section className="hero px-5"><div className="hero-grid relative z-10 mx-auto grid min-h-[615px] max-w-[1160px] items-center gap-12 py-14 md:grid-cols-[1.12fr_.88fr]">
      <div className="fade-up"><p className="eyebrow flex items-center gap-2"><span className="h-px w-7 bg-[#39867f]"/> Specialist endodontic care · Delhi NCR</p><h1 className="serif mt-6 max-w-[730px] text-[clamp(3.5rem,7.4vw,6.4rem)] leading-[.88] tracking-[-.025em] text-[#153d50]">Preserving natural teeth through <em className="text-[#267d79]">expert</em> endodontic care.</h1>
        <p className="mt-7 max-w-[500px] text-lg leading-8 text-[#506c77]">A thoughtful, clear approach to specialist care—rooted in careful diagnosis and a conversation that starts with you.</p>
        <div className="mt-8 flex flex-wrap gap-3"><a href="#book" className="btn-primary">Book appointment <ArrowRight size={17}/></a><Link href="/refer-a-patient" className="btn-outline">Refer a patient <ArrowRight size={16}/></Link></div>
        <div className="mt-9 flex items-center gap-3 text-sm text-[#4a6973]"><span className="grid h-8 w-8 place-items-center rounded-full bg-white text-[#32847c]"><Check size={16}/></span><span>Personalised care, clear communication</span></div>
      </div>
      <div className="relative mx-auto w-full max-w-[425px]">
        <div className="absolute -right-8 -top-7 h-32 w-32 rounded-full border border-[#9bc8c5]/70"/><div className="portrait-placeholder relative aspect-[.83] overflow-hidden rounded-t-[48%] rounded-b-[2rem] border-[10px] border-white/75 shadow-[0_24px_55px_rgba(31,76,83,.16)]" role="img" aria-label="Generic portrait placeholder; image is not Dr Charu Makhija">
          <div className="absolute inset-x-4 bottom-5 z-10 rounded-xl bg-[#143e50]/90 px-4 py-3 text-center text-xs tracking-wide text-white">Portrait placeholder · Dr Makhija’s photograph to come</div></div>
        <div className="absolute -bottom-5 -left-10 rounded-2xl border border-[#d9e8e7] bg-white px-5 py-4 shadow-lg"><div className="serif text-3xl text-[#1c6570]">15+</div><div className="text-[.68rem] font-semibold uppercase tracking-wider text-[#627a81]">years of experience</div></div>
      </div>
    </div></section>
    <section className="border-y border-[#e2ecec] bg-[#fbfdfc] px-5 py-7"><div className="mx-auto grid max-w-[1160px] gap-5 sm:grid-cols-2 lg:grid-cols-4">
      {[['15+ years','Clinical experience'],['BDS · MDS','Conservative Dentistry and Endodontics'],['MBA','Hospital Management'],['Listening first','Personalised care']].map(([a,b])=><div key={a} className="flex items-start gap-3"><span className="mt-1 h-2 w-2 rounded-full bg-[#32877e]"/><p><b className="block text-sm text-[#21495a]">{a}</b><span className="text-xs leading-5 text-[#6a7f84]">{b}</span></p></div>)}
    </div></section>
    <section id="about" className="section-pad bg-[#fbfdfc]"><div className="mx-auto grid max-w-[1120px] gap-12 md:grid-cols-[.72fr_1.28fr]">
      <div><p className="eyebrow">Meet your specialist</p><h2 className="serif mt-4 text-5xl leading-[.96] text-[#173f51]">Care built on trust and conversation.</h2><div className="mt-8 h-px w-16 bg-[#6ea9a3]"/></div>
      <div className="max-w-[700px] text-[1.02rem] leading-8 text-[#536e77]"><p>Dr Charu Makhija is an experienced Restorative Dentist and Endodontist with over 15 years of clinical experience. She is dedicated to helping patients preserve their natural teeth through careful diagnosis, advanced treatment techniques and gentle, personalised dental care.</p><p className="mt-5">She completed her BDS and MDS in Conservative Dentistry and Endodontics and also holds an MBA in Hospital Management, complementing her clinical expertise with a broader understanding of healthcare management and professional leadership. She remains actively involved in continuing education, research and academics.</p><p className="mt-5">Known professionally through her copyrighted identity, ‘The Pulp Doctor,’ Dr Makhija believes that quality dental care begins with trust and clear communication. She takes the time to listen to each patient’s concerns, explain treatment options in simple language and create a treatment plan that prioritises comfort, safety and long-term oral health.</p><details className="mt-5"><summary className="flex cursor-pointer items-center gap-2 text-sm font-bold text-[#277a78]">Read more about Dr Makhija <ChevronDown size={15}/></summary><p className="mt-4">Alongside her clinical practice, Dr Makhija is a dedicated mentor and educator. She conducts lectures, hands-on workshops and clinical training programmes for dentists at different stages of their professional journeys.</p><p className="mt-4">With a thoughtful approach, attention to detail and a genuine commitment to patient wellbeing, Dr Charu Makhija strives to make every patient feel heard, reassured and confident throughout their treatment journey.</p></details></div>
    </div></section>
    <section id="care" className="section-pad bg-[#eaf3f4]"><div className="mx-auto max-w-[1160px]"><div className="flex flex-wrap items-end justify-between gap-5"><div><p className="eyebrow">Specialist care</p><h2 className="serif mt-3 text-5xl text-[#173f51]">Care with a clear purpose.</h2></div><p className="max-w-md leading-7 text-[#5a737b]">Treatment is guided by diagnosis and discussion. We’ll explain the options relevant to your needs.</p></div>
      <div className="mt-10 grid gap-4 md:grid-cols-[1.3fr_1fr_1fr]"><article className="rounded-3xl bg-[#16566a] p-7 text-white md:row-span-2"><span className="text-xs font-bold uppercase tracking-[.18em] text-[#9dd1c9]">Specialist focus</span><h3 className="serif mt-16 text-4xl">Root Canal Treatment</h3><p className="mt-4 max-w-sm leading-7 text-[#d0e2e2]">Endodontic care focused on preserving your natural tooth, with careful diagnosis and a treatment plan explained in clear language.</p><a href="#book" className="mt-8 inline-flex items-center gap-2 text-sm font-bold text-white underline underline-offset-4">Discuss an appointment <ArrowRight size={15}/></a></article>
        {[['Care begins with listening','Your concerns and clinical history help guide the conversation.'],['Understand your options','Clinical findings and relevant choices are explained before planning care.'],['A plan made together','The next step is decided around your individual needs and wellbeing.']].map(([title,copy],i)=><article key={title} className="flex min-h-44 flex-col justify-between rounded-3xl border border-[#d6e5e5] bg-white p-6"><span className="text-xs font-bold uppercase tracking-[.16em] text-[#5f9590]">Care principle · 0{i+1}</span><h3 className="text-xl font-bold text-[#22485a]">{title}</h3><p className="text-sm leading-6 text-[#637981]">{copy}</p></article>)}
      </div><p className="mt-5 text-xs text-[#71848a]">The appropriate care is determined after an individual clinical assessment.</p>
    </div></section>
    <section className="section-pad bg-[#f9fcfb]"><div className="mx-auto max-w-[1160px]"><p className="eyebrow">The experience</p><h2 className="serif mt-3 text-5xl text-[#173f51]">Thoughtful at every step.</h2><div className="mt-9 grid gap-8 md:grid-cols-3">
      {[['01','Listen carefully','We begin with your concerns and take time to understand what brought you in.'],['02','Explain clearly','You’ll hear what we find, what the options are, and what each step involves.'],['03','Plan together','Care is planned around your clinical needs, comfort and long-term oral health.']].map(([n,title,body])=><article className="border-t-2 border-[#85b9b3] pt-5" key={n}><span className="serif text-3xl text-[#73a6a1]">{n}</span><h3 className="mt-4 text-xl font-bold text-[#24495a]">{title}</h3><p className="mt-3 leading-7 text-[#627981]">{body}</p></article>)}
    </div></div></section>
    <section id="locations" className="section-pad bg-[#eaf3f4]"><div className="mx-auto max-w-[1160px]"><div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="eyebrow">Where to find us</p><h2 className="serif mt-3 text-5xl text-[#173f51]">Clinic locations.</h2></div><p className="max-w-sm text-sm leading-6 text-[#60787f]">Clinic days and hours are published by the practice and may vary. Check availability before travelling.</p></div><LocationCards locations={locations} loading={locationsQuery.isLoading} error={locationsQuery.isError} retry={()=>locationsQuery.refetch()}/></div></section>
    <section className="bg-[#17495a] px-5 py-12 text-white"><div className="mx-auto flex max-w-[1160px] flex-col justify-between gap-5 md:flex-row md:items-center"><div><p className="eyebrow !text-[#9bd0c8]">Urgent concern?</p><h2 className="serif mt-2 text-4xl">Sunday appointments are by publication only.</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[#cee0df]">Sunday is reserved for emergency appointments and is closed by default. Emergency slots are available only when the doctor publishes them.</p></div><a href="#book" className="btn-outline shrink-0 !border-white/50 !text-white hover:!bg-white/10">Check availability <ArrowRight size={16}/></a></div></section>
    <section className="section-pad bg-[#fbfdfc]"><div className="mx-auto grid max-w-[1160px] items-center gap-10 md:grid-cols-[1fr_1fr]"><div><p className="eyebrow">For referring dentists</p><h2 className="serif mt-3 text-5xl leading-none text-[#173f51]">A considered referral. A clear handover.</h2><p className="mt-5 max-w-lg leading-7 text-[#58717a]">Share the clinical context, tooth details and restorative plan securely. The referral form includes an interactive FDI chart and a review step.</p><Link href="/refer-a-patient" className="btn-primary mt-7">Refer a patient <ArrowRight size={16}/></Link></div><div className="rounded-[2rem] bg-[#edf5f4] p-8"><div className="grid h-14 w-14 place-items-center rounded-2xl bg-white text-[#2f827a]"><HeartHandshake size={26}/></div><p className="serif mt-7 text-3xl text-[#1d4c5a]">Colleague to colleague.</p><p className="mt-3 leading-7 text-[#5b747b]">Dr Makhija conducts lectures, hands-on workshops and clinical training programmes for dentists at different stages of their professional journeys.</p></div></div></section>
    <section className="section-pad bg-[#eaf3f4]"><div className="mx-auto max-w-[900px]"><p className="eyebrow">A few helpful notes</p><h2 className="serif mt-3 text-5xl text-[#173f51]">Questions, answered.</h2><div className="mt-8 divide-y divide-[#d3e2e3]">{[
      ['What should I expect at my appointment?','Your concerns and clinical needs will be discussed, and the findings and relevant options explained clearly.'],
      ['Can I book a Sunday appointment?','Sunday is closed by default. Emergency appointments are available only when specific Sunday slots have been published.'],
      ['Where are appointments available?','The practice publishes appointments across Gurugram, Model Town and Karol Bagh. Select a clinic and date to see live availability.'],
      ['I am a dentist. How do I refer a patient?','Use the dedicated referral form to provide patient details, selected FDI teeth, request and restorative information. Review everything before submitting.'],
    ].map(([question,answer])=><details key={question} className="group py-5"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 font-bold text-[#274b5a]">{question}<ChevronDown size={17} className="shrink-0 text-[#49877f] transition-transform group-open:rotate-180"/></summary><p className="mt-3 max-w-[760px] leading-7 text-[#5c737b]">{answer}</p></details>)}</div></div></section>
    <Booking locations={locations}/>
    <section id="contact" className="section-pad bg-[#fbfdfc]"><div className="mx-auto grid max-w-[1160px] gap-8 md:grid-cols-[1fr_auto] md:items-end"><div><p className="eyebrow">Get in touch</p><h2 className="serif mt-3 text-5xl text-[#173f51]">Start with a conversation.</h2><p className="mt-4 max-w-lg leading-7 text-[#60767d]">Choose an appointment location above to view the practice’s live availability.</p><a className="mt-4 inline-block font-semibold text-[#277a78] underline underline-offset-4" href="mailto:drcharu.25@gmail.com">drcharu.25@gmail.com</a><p className="mt-2 text-xs text-[#72858a]">Phone contact will be added when supplied by the practice.</p></div><a href="#book" className="btn-primary">Choose an appointment <ArrowRight size={16}/></a></div></section>
    <div className="sr-only" aria-live="polite">{health.isError?'Practice services are currently unavailable.':''}</div>
  </main></Shell>;
}

type ReferralForm = Omit<ReferralInput,'selectedTeeth'|'authorizationConfirmed'|'uploadIds'> & {selectedTeeth:number[];authorizationConfirmed:boolean;uploadIds:string[]};
const initialReferral=():ReferralForm=>({referralDate:today(),dentistName:'',practiceName:'',dentistPhone:'',dentistEmail:'',patientName:'',patientPhone:'',dateOfBirth:'',selectedTeeth:[],requestType:requestOptions[1],existingRestoration:restorationOptions[0],coronalRestoration:coronalOptions[0],restorativePlan:'',clinicalComments:'',preferredDate:'',preferredTime:'',uploadIds:[],authorizationConfirmed:false});
function ReferralPage() {
  const [form,setForm]=useState<ReferralForm>(initialReferral); const [review,setReview]=useState(false); const [done,setDone]=useState<{reference:string;message:string}|null>(null); const [error,setError]=useState('');
  const submit=useCreateReferral(); const upload=useReserveReferralUpload();
  const set=(key:keyof ReferralForm,value:unknown)=>setForm(old=>({...old,[key]:value}));
  const changeTeeth=(tooth:number)=>set('selectedTeeth',form.selectedTeeth.includes(tooth)?form.selectedTeeth.filter(t=>t!==tooth):[...form.selectedTeeth,tooth]);
  const addFile=async(file:File)=>{setError('');if(form.uploadIds.length>=5){setError('You may attach up to five files.');return}if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size<1||file.size>10485760){setError('Choose a JPEG, PNG, WebP or PDF file up to 10 MB.');return}
    try {const target=await upload.mutateAsync({data:{fileName:file.name,contentType:file.type as 'image/jpeg'|'image/png'|'image/webp'|'application/pdf',fileSize:file.size}});
      const response=await fetch(`/api/referral-uploads/${encodeURIComponent(target.uploadId)}/content`,{method:'PUT',headers:{'Content-Type':file.type,'x-upload-token':target.uploadToken},body:file}); if(!response.ok)throw new Error('The secure file transfer failed. Your referral form is unchanged.');set('uploadIds',[...form.uploadIds,target.uploadId]);
    } catch(e){setError(errorText(e));}};
  const submitReferral=()=>{setError('');submit.mutate({data:{...form,dateOfBirth:form.dateOfBirth||null,preferredDate:form.preferredDate||null,preferredTime:form.preferredTime||null,selectedTeeth:form.selectedTeeth as ReferralInput['selectedTeeth'],authorizationConfirmed:true}}, {onSuccess:r=>setDone({reference:r.reference,message:r.message}),onError:e=>setError(errorText(e))});};
  const requiredReady=!!form.dentistName&&!!form.practiceName&&!!form.dentistPhone&&!!form.dentistEmail&&!!form.patientName&&!!form.patientPhone&&!!form.selectedTeeth.length&&form.authorizationConfirmed;
  return <Shell><main className="min-h-[80dvh] bg-[#edf5f5] px-4 py-10 sm:px-6"><div className="mx-auto max-w-[1000px]">
    <div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="eyebrow">For dental colleagues</p><h1 className="serif mt-2 text-5xl text-[#173f51]">Patient referral</h1><p className="mt-2 max-w-xl text-[#5b747c]">A clear clinical handover. Complete the details, review, then submit securely.</p></div><button className="btn-outline !py-2.5 print:hidden" onClick={()=>window.print()}><Printer size={16}/> Print form</button></div>
    {done ? <div className="soft-card rounded-3xl px-6 py-14 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-[#e0f1ec] text-[#26776f]"><Check size={26}/></span><p className="eyebrow mt-5">Referral received</p><h2 className="serif mt-2 text-4xl text-[#173f51]">Thank you for the handover.</h2><p className="mt-4 text-[#58717a]">{done.message}</p><div className="mx-auto mt-5 inline-block rounded-xl bg-[#eef5f5] px-5 py-3 text-sm">Referral reference <strong className="ml-2 text-[#14566a]">{done.reference}</strong></div><p className="mx-auto mt-4 max-w-lg text-xs leading-5 text-[#71848a]">This confirms submission only; it does not confirm clinical acceptance or an appointment.</p><button className="btn-outline mt-7" onClick={()=>{setForm(initialReferral());setDone(null);setReview(false)}}>Start another referral</button></div> :
    <div className="soft-card rounded-3xl p-5 sm:p-9">
      <div className="mb-8 flex items-center gap-3"><span className={`grid h-8 w-8 place-items-center rounded-full text-sm font-bold ${review?'bg-[#dcebea] text-[#527873]':'bg-[#176d70] text-white'}`}>1</span><span className={`h-px w-10 ${review?'bg-[#9dbdb9]':'bg-[#d2e0e1]'}`}/><span className={`grid h-8 w-8 place-items-center rounded-full text-sm font-bold ${review?'bg-[#176d70] text-white':'bg-[#eaf1f1] text-[#71858a]'}`}>2</span><span className="ml-1 text-sm font-semibold text-[#45626b]">{review?'Review referral':'Referral details'}</span></div>
      {review ? <div className="space-y-6">
        <div className="rounded-2xl bg-[#f2f7f6] p-5"><h2 className="font-bold text-[#21485a]">Referral and patient details</h2><div className="mt-4 grid gap-3 text-sm sm:grid-cols-2"><p><b>Referring dentist:</b> {form.dentistName}</p><p><b>Practice:</b> {form.practiceName}</p><p><b>Phone:</b> {form.dentistPhone}</p><p><b>Email:</b> {form.dentistEmail}</p><p><b>Patient:</b> {form.patientName}</p><p><b>Patient phone:</b> {form.patientPhone}</p><p><b>Referral date:</b> {form.referralDate}</p><p><b>Date of birth:</b> {form.dateOfBirth||'Not provided'}</p></div></div>
        <div className="grid gap-4 sm:grid-cols-2"><div className="rounded-2xl border border-[#dce8e8] p-5"><h3 className="font-bold text-[#21485a]">Clinical request</h3><p className="mt-3 text-sm"><b>Selected teeth:</b> {form.selectedTeeth.join(', ')}</p><p className="mt-2 text-sm"><b>Request:</b> {form.requestType}</p><p className="mt-2 text-sm"><b>Existing restoration:</b> {form.existingRestoration}</p><p className="mt-2 text-sm"><b>Coronal restoration:</b> {form.coronalRestoration}</p></div><div className="rounded-2xl border border-[#dce8e8] p-5"><h3 className="font-bold text-[#21485a]">Additional information</h3><p className="mt-3 whitespace-pre-wrap text-sm"><b>Restorative plan:</b> {form.restorativePlan||'Not provided'}</p><p className="mt-2 whitespace-pre-wrap text-sm"><b>Clinical comments:</b> {form.clinicalComments||'Not provided'}</p><p className="mt-2 text-sm"><b>Preferred appointment:</b> {form.preferredDate||'Not specified'} {form.preferredTime}</p><p className="mt-2 text-sm"><b>Attachments:</b> {form.uploadIds.length?`${form.uploadIds.length} secure file(s)`:'None'}</p></div></div>
        <div className="flex flex-wrap justify-between gap-3"><button className="btn-outline" onClick={()=>setReview(false)}>Back to edit</button><button className="btn-primary" disabled={submit.isPending} onClick={submitReferral}>{submit.isPending?'Submitting…':'Submit referral'} <ArrowRight size={16}/></button></div>
      </div> : <form onSubmit={e=>{e.preventDefault();setError('');if(!requiredReady){setError('Complete the required fields, select at least one tooth and confirm authorisation before review.');return}setReview(true)}} className="space-y-8">
        <fieldset><legend className="mb-4 text-lg font-bold text-[#1d4657]">Referring dentist</legend><div className="grid gap-4 sm:grid-cols-2"><Field label="Referral date" type="date" value={form.referralDate} set={v=>set('referralDate',v)} required/><Field label="Dentist’s name" value={form.dentistName} set={v=>set('dentistName',v)} required/><Field label="Clinic / practice name" value={form.practiceName} set={v=>set('practiceName',v)} required/><Field label="Phone" type="tel" value={form.dentistPhone} set={v=>set('dentistPhone',v)} required/><Field label="Email" type="email" value={form.dentistEmail} set={v=>set('dentistEmail',v)} required/></div></fieldset>
        <fieldset><legend className="mb-4 text-lg font-bold text-[#1d4657]">Patient details</legend><div className="grid gap-4 sm:grid-cols-2"><Field label="Patient name" value={form.patientName} set={v=>set('patientName',v)} required/><Field label="Patient phone" type="tel" value={form.patientPhone} set={v=>set('patientPhone',v)} required/><Field label="Date of birth (only if clinically necessary)" type="date" value={form.dateOfBirth||''} set={v=>set('dateOfBirth',v)}/></div></fieldset>
        <fieldset><legend className="mb-1 text-lg font-bold text-[#1d4657]">Tooth selection</legend><p className="mb-4 text-sm text-[#6a7f85]">Adult permanent teeth · FDI numbering. Use Tab and arrow keys, or Space / Enter to select.</p><div className="rounded-2xl bg-[#f1f6f6] p-4 sm:p-6"><div className="mx-auto max-w-[560px]"><p className="mb-2 text-center text-[.65rem] font-bold uppercase tracking-[.18em] text-[#70868b]">Upper · right to left</p><div className="flex justify-center gap-1 sm:gap-2">{fdi[0].map(n=><Tooth key={n} number={n} selected={form.selectedTeeth.includes(n)} toggle={()=>changeTeeth(n)}/>)}</div><div className="my-4 border-t border-dashed border-[#bdcecf]"/><div className="flex justify-center gap-1 sm:gap-2">{fdi[1].map(n=><Tooth key={n} number={n} selected={form.selectedTeeth.includes(n)} toggle={()=>changeTeeth(n)}/>)}</div><p className="mb-2 mt-2 text-center text-[.65rem] font-bold uppercase tracking-[.18em] text-[#70868b]">Lower · left to right</p><div className="flex justify-center gap-1 sm:gap-2">{fdi[2].slice().reverse().map(n=><Tooth key={n} number={n} selected={form.selectedTeeth.includes(n)} toggle={()=>changeTeeth(n)}/>)}</div><div className="my-4 border-t border-dashed border-[#bdcecf]"/><div className="flex justify-center gap-1 sm:gap-2">{fdi[3].slice().reverse().map(n=><Tooth key={n} number={n} selected={form.selectedTeeth.includes(n)} toggle={()=>changeTeeth(n)}/>)}</div></div><p className="mt-4 text-center text-xs text-[#52717a]" aria-live="polite">Selected: {form.selectedTeeth.length?form.selectedTeeth.slice().sort().join(', '):'None yet'}</p></div></fieldset>
        <fieldset><legend className="mb-4 text-lg font-bold text-[#1d4657]">Referral request and restoration</legend><div className="grid gap-4 sm:grid-cols-2"><SelectField label="Request" value={form.requestType} values={requestOptions} set={v=>set('requestType',v)}/><SelectField label="Existing restoration" value={form.existingRestoration} values={restorationOptions} set={v=>set('existingRestoration',v)}/><SelectField label="Requested coronal restoration" value={form.coronalRestoration} values={coronalOptions} set={v=>set('coronalRestoration',v)}/></div></fieldset>
        <fieldset><legend className="mb-4 text-lg font-bold text-[#1d4657]">Clinical context</legend><div className="grid gap-4 sm:grid-cols-2"><TextAreaField label="Restorative treatment plan" value={form.restorativePlan||''} set={v=>set('restorativePlan',v)} max={2000}/><TextAreaField label="Comments / additional clinical information" value={form.clinicalComments||''} set={v=>set('clinicalComments',v)} max={4000}/><Field label="Preferred appointment date (optional)" type="date" value={form.preferredDate||''} set={v=>set('preferredDate',v)}/><Field label="Preferred time (optional)" type="time" value={form.preferredTime||''} set={v=>set('preferredTime',v)}/></div><label className="mt-4 block text-sm font-semibold text-[#315364]">X-ray / CBCT attachment <span className="font-normal text-[#74878c]">(optional · JPEG, PNG, WebP or PDF, up to 10 MB; maximum 5 files)</span><input className="field mt-2 bg-white" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" disabled={upload.isPending||form.uploadIds.length>=5} onChange={e=>{const file=e.target.files?.[0];if(file)void addFile(file);e.currentTarget.value=''}}/></label>{upload.isPending&&<p className="mt-2 text-xs text-[#4c7778]">Requesting secure upload…</p>}{form.uploadIds.length>0&&<ul className="mt-2 text-xs text-[#47706f]">{form.uploadIds.map((id,i)=><li key={id} className="flex justify-between">Secure attachment {i+1}<button type="button" className="underline" onClick={()=>set('uploadIds',form.uploadIds.filter(x=>x!==id))}>Remove</button></li>)}</ul>}</fieldset>
        <label className="flex items-start gap-3 rounded-xl border border-[#d7e5e5] bg-[#f7faf9] p-4 text-sm leading-6 text-[#4d6871]"><input type="checkbox" className="mt-1 h-4 w-4 accent-[#176d70]" checked={form.authorizationConfirmed} onChange={e=>set('authorizationConfirmed',e.target.checked)}/><span>I confirm that appropriate patient consent / authorisation has been obtained to share the information in this referral, including any attached images.</span></label>
        {error&&<p role="alert" className="rounded-xl bg-[#fcf1ee] p-3 text-sm text-[#934a3f]">{error}</p>}
        <div className="flex flex-wrap justify-between gap-3"><Link href="/" className="btn-outline">Return to practice website</Link><button type="submit" className="btn-primary">Review referral <ArrowRight size={16}/></button></div>
      </form>}
    </div>}
    <p className="mx-auto mt-5 max-w-3xl text-center text-xs leading-5 text-[#73868b]">Privacy and consent wording is a placeholder for practice approval. Submission confirms receipt only; it does not constitute acceptance or appointment confirmation.</p>
  </div></main></Shell>;
}
function Field({label,value,set,type='text',required=false}:{label:string;value:string;set:(v:string)=>void;type?:string;required?:boolean}) {return <label className="block text-sm font-semibold text-[#315364]">{label}{required&&<span className="text-[#ad5d50]"> *</span>}<input className="field mt-2 bg-white" type={type} required={required} value={value} onChange={e=>set(e.target.value)}/></label>;}
function TextAreaField({label,value,set,max}:{label:string;value:string;set:(v:string)=>void;max:number}) {return <label className="block text-sm font-semibold text-[#315364]">{label}<textarea className="field mt-2 min-h-28 bg-white" maxLength={max} value={value} onChange={e=>set(e.target.value)}/></label>;}
function SelectField({label,value,values,set}:{label:string;value:string;values:string[];set:(v:string)=>void}) {return <label className="block text-sm font-semibold text-[#315364]">{label}<select className="field mt-2 bg-white" value={value} onChange={e=>set(e.target.value)}>{values.map(v=><option key={v}>{v}</option>)}</select></label>;}
function Tooth({number,selected,toggle}:{number:number;selected:boolean;toggle:()=>void}) {return <button type="button" className={`tooth ${selected?'selected':''}`} aria-pressed={selected} aria-label={`Tooth ${number}${selected?', selected':''}`} onClick={toggle} data-testid={`tooth-${number}`}>{number}</button>;}

function AdminLogin() {
  const [,navigate]=useLocation(); const login=useAdminLogin(); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [message,setMessage]=useState('');
  return <main className="grid min-h-[100dvh] bg-[#eaf3f4] md:grid-cols-[1.1fr_.9fr]"><div className="hidden flex-col justify-between bg-[#153f51] p-12 text-white md:flex"><Brand/><div><p className="eyebrow !text-[#95c7c0]">Practice operations</p><h1 className="serif mt-5 max-w-xl text-6xl leading-[.95]">A quieter way to keep the day in order.</h1><p className="mt-5 max-w-lg leading-7 text-[#c4d8d8]">Protected access for the practice team.</p></div><p className="text-xs text-[#a7c0c2]">THE PULP DOCTOR · Dr Charu Makhija</p></div>
    <div className="flex items-center justify-center px-5 py-12"><form className="soft-card w-full max-w-[430px] rounded-3xl p-7 sm:p-9" onSubmit={e=>{e.preventDefault();setMessage('');login.mutate({data:{email,password}},{onSuccess:()=>navigate('/admin'),onError:error=>setMessage(errorText(error))})}}>
      <div className="md:hidden"><Brand/></div><p className="eyebrow mt-7">Administrator sign in</p><h2 className="serif mt-2 text-4xl text-[#173f51]">Welcome back.</h2><p className="mt-3 text-sm leading-6 text-[#60777f]">Sign in with your practice administrator account.</p>
      <label className="mt-7 block text-sm font-semibold text-[#315364]">Email<input className="field mt-2" type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="mt-4 block text-sm font-semibold text-[#315364]">Password<input className="field mt-2" type="password" autoComplete="current-password" minLength={12} required value={password} onChange={e=>setPassword(e.target.value)}/></label>
      {message&&<p className="mt-4 rounded-lg bg-[#fcf1ee] p-3 text-sm text-[#934a3f]" role="alert">{message}</p>}
      <button className="btn-primary mt-6 w-full" disabled={login.isPending}>{login.isPending?'Signing in…':'Sign in securely'} <ArrowRight size={16}/></button><Link href="/" className="mt-5 block text-center text-sm font-semibold text-[#397c7a]">Back to public website</Link>
    </form></div></main>;
}

function AdminDashboard() {
  const [,navigate]=useLocation(); const qc=useQueryClient(); const session=useGetAdminSession({query:{queryKey:getGetAdminSessionQueryKey(),retry:false}}); const dashboard=useGetAdminDashboard({query:{queryKey:getGetAdminDashboardQueryKey(),enabled:!!session.data, retry:false}}); const locationsQ=useListLocations(); const locations=locationsQ.data??[];
  const [tab,setTab]=useState<'overview'|'appointments'|'referrals'|'schedule'|'notifications'>('overview'); const [filterDate,setFilterDate]=useState(today()); const [selectedLocation,setSelectedLocation]=useState(''); const [message,setMessage]=useState('');
  const apptParams=useMemo(()=>({from:filterDate,to:filterDate,...(selectedLocation?{locationId:selectedLocation}:{})}),[filterDate,selectedLocation]);
  const appointments=useListAdminAppointments(apptParams,{query:{queryKey:getListAdminAppointmentsQueryKey(apptParams),enabled:!!session.data,retry:false}});
  const referrals=useListAdminReferrals(undefined,{query:{queryKey:getListAdminReferralsQueryKey(),enabled:!!session.data&&tab==='referrals',retry:false}});
  const schedules=useListAdminSchedules({query:{queryKey:getListAdminSchedulesQueryKey(),enabled:!!session.data&&tab==='schedule',retry:false}});
  const notificationQuery=useListAdminNotifications({query:{queryKey:getListAdminNotificationsQueryKey(),enabled:!!session.data&&tab==='notifications',retry:false}});
  const overrideParams=useMemo(()=>({from:today(),to:new Date(Date.now()+1000*60*60*24*60).toLocaleDateString('en-CA')}),[]);
  const availabilityOverrides=useListAdminAvailabilityOverrides(overrideParams,{query:{queryKey:getListAdminAvailabilityOverridesQueryKey(overrideParams),enabled:!!session.data&&tab==='schedule',retry:false}});
  const logout=useAdminLogout(); const phoneBooking=useCreatePhoneAppointment(); const cancel=useCancelAdminAppointment(); const reschedule=useRescheduleAdminAppointment(); const updateReferral=useUpdateReferralStatus(); const updateSchedule=useUpdateAdminSchedule(); const override=useCreateAdminAvailabilityOverride();
  const retryNotification=useRetryAdminNotification(); const attachmentAccess=useRequestReferralAttachmentAccessUrl(); const updateLocation=useUpdateAdminLocation();
  const [phoneForm,setPhoneForm]=useState({locationId:'',date:today(),slotId:'',patientName:'',phone:'',email:'',appointmentType:'',notes:'',internalNotes:''});
  const [overrideForm,setOverrideForm]=useState({locationId:'',date:today(),kind:'extra',slots:'',reason:''});
  const [adminActionId,setAdminActionId]=useState('');
  if(session.isLoading)return <AdminLoading/>;
  if(!session.data)return <AdminLogin/>;
  const refresh=()=>{void qc.invalidateQueries({queryKey:getGetAdminDashboardQueryKey()});void qc.invalidateQueries({queryKey:getListAdminAppointmentsQueryKey()});void qc.invalidateQueries({queryKey:getListAdminReferralsQueryKey()});void qc.invalidateQueries({queryKey:getListAdminSchedulesQueryKey()});};
  const adminError=(error:unknown)=>setMessage(errorText(error));
  return <main className="min-h-[100dvh] bg-[#eff5f5]">
    <header className="border-b border-[#d8e5e5] bg-white px-5 py-4"><div className="mx-auto flex max-w-[1350px] flex-wrap items-center justify-between gap-4"><Brand/><div className="flex items-center gap-4"><span className="hidden text-sm text-[#58717a] sm:block">Signed in as <b>{session.data.displayName}</b></span><button className="btn-outline !px-4 !py-2 text-sm" onClick={()=>logout.mutate(undefined,{onSuccess:()=>{void qc.invalidateQueries({queryKey:getGetAdminSessionQueryKey()});navigate('/admin/login')},onError:adminError})}><LogOut size={15}/> Sign out</button></div></div></header>
    <div className="mx-auto max-w-[1350px] px-4 py-8 sm:px-6"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="eyebrow">Practice administration</p><h1 className="serif mt-2 text-5xl text-[#173f51]">Good day, {session.data.displayName.split(' ')[0]}.</h1><p className="mt-2 text-sm text-[#637982]">Private practice operations · Handle patient information with care</p></div><button className="btn-outline !px-4 !py-2.5 text-sm" onClick={refresh}><RefreshCw size={15}/> Refresh data</button></div>
      <nav className="mt-8 flex gap-2 overflow-x-auto border-b border-[#d6e4e4]" aria-label="Administration sections">{(['overview','appointments','referrals','schedule','notifications'] as const).map(item=><button key={item} className={`shrink-0 border-b-2 px-4 py-3 text-sm font-bold capitalize ${tab===item?'border-[#287c78] text-[#176d70]':'border-transparent text-[#698087]'}`} onClick={()=>setTab(item)}>{item}</button>)}</nav>
      {message&&<p role="alert" className="mt-4 flex items-center gap-2 rounded-xl bg-[#fcf1ee] p-3 text-sm text-[#934a3f]"><AlertCircle size={16}/>{message}<button className="ml-auto underline" onClick={()=>setMessage('')}>Dismiss</button></p>}
      {tab==='overview'&&<><div className="mt-6 grid gap-4 sm:grid-cols-3">{[['Today',dashboard.data?.todayAppointments],['Upcoming',dashboard.data?.upcomingAppointments],['Referrals to review',dashboard.data?.pendingReferrals]].map(([title,value])=><div className="soft-card rounded-2xl p-5" key={title as string}><p className="text-xs font-bold uppercase tracking-widest text-[#658087]">{title}</p><p className="serif mt-3 text-4xl text-[#1a5261]">{dashboard.isLoading?'—':value??'—'}</p></div>)}</div>
        <section className="soft-card mt-6 rounded-2xl p-5 sm:p-7"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="eyebrow">Daily list</p><h2 className="mt-2 text-xl font-bold text-[#21485a]">Next appointments</h2></div><button className="btn-outline !py-2 text-sm" onClick={()=>setTab('appointments')}>View appointments <ArrowRight size={14}/></button></div><AppointmentTable items={dashboard.data?.nextAppointments??[]} empty={dashboard.isLoading?'Loading appointments…':'No upcoming appointments are available.'} onCancel={(id)=>{setAdminActionId(id);setTab('appointments')}}/></section></>}
      {tab==='appointments'&&<section className="mt-6 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><div className="soft-card rounded-2xl p-5 sm:p-7"><div className="flex flex-wrap items-end gap-3"><label className="text-sm font-semibold text-[#315364]">Date<input className="field mt-1" type="date" value={filterDate} onChange={e=>setFilterDate(e.target.value)}/></label><label className="text-sm font-semibold text-[#315364]">Location<select className="field mt-1" value={selectedLocation} onChange={e=>setSelectedLocation(e.target.value)}><option value="">All locations</option>{locations.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></label><button className="btn-outline !py-2 text-sm" onClick={()=>appointments.refetch()}>Refresh</button></div>
          {appointments.isError?<ErrorPanel retry={()=>appointments.refetch()}/>:<AppointmentTable items={appointments.data??[]} empty={appointments.isLoading?'Loading protected appointment records…':'No appointments match these filters.'} onCancel={id=>{const reason=prompt('Reason for cancellation (optional):')??'';if(confirm('Confirm cancellation of this appointment?'))cancel.mutate({appointmentId:id,data:{confirmed:true,reason}},{onSuccess:refresh,onError:adminError})}} onReschedule={item=>{const newDate=prompt('New date (YYYY-MM-DD):',item.date);if(!newDate)return;const slotId=prompt('Published slot ID for the selected date:');if(!slotId)return;if(confirm('Confirm rescheduling to the selected published slot?'))reschedule.mutate({appointmentId:item.id,data:{confirmed:true,locationId:item.locationId,date:newDate,slotId}},{onSuccess:refresh,onError:adminError})}}/>}
          {adminActionId&&<p className="mt-3 text-xs text-[#5f777d]">Choose a row action below; rescheduling requires a published slot.</p>}
        </div><PhoneBooking locations={locations} form={phoneForm} set={setPhoneForm} submit={payload=>phoneBooking.mutate({data:payload},{onSuccess:()=>{setMessage('Phone appointment reserved successfully.');refresh()},onError:adminError})} pending={phoneBooking.isPending}/></section>}
      {tab==='referrals'&&<section className="soft-card mt-6 rounded-2xl p-5 sm:p-7"><p className="eyebrow">Protected clinical information</p><h2 className="mt-2 text-xl font-bold text-[#21485a]">Dentist referrals</h2>{referrals.isError?<ErrorPanel retry={()=>referrals.refetch()}/>:!referrals.data?.length?<p className="mt-5 rounded-xl bg-[#f0f6f5] p-5 text-sm text-[#657b81]">{referrals.isLoading?'Loading referrals…':'No referrals are available.'}</p>:<div className="mt-5 space-y-3">{referrals.data.map(ref=><article key={ref.id} className="rounded-xl border border-[#dbe7e7] bg-white p-4"><div className="flex flex-wrap justify-between gap-3"><div><p className="font-bold text-[#234a5b]">{ref.patientName} · {ref.reference}</p><p className="mt-1 text-sm text-[#637a81]">{ref.dentistName} · {ref.practiceName} · teeth {ref.selectedTeeth.join(', ')}</p><p className="mt-1 text-xs text-[#70858b]">{ref.requestType} · Received {new Date(ref.createdAt).toLocaleDateString()}</p></div><label className="text-xs font-bold text-[#577078]">Status<select className="field mt-1 !w-auto" value={ref.status} onChange={e=>updateReferral.mutate({referralId:ref.id,data:{status:e.target.value as 'received'|'reviewing'|'contacted'|'scheduled'|'closed',internalNotes:ref.internalNotes}},{onSuccess:refresh,onError:adminError})}>{['received','reviewing','contacted','scheduled','closed'].map(s=><option key={s}>{s}</option>)}</select></label></div><p className="mt-3 whitespace-pre-wrap text-sm text-[#5e747b]">{ref.clinicalComments||'No additional comments provided.'}</p>
        {(ref.uploadIds??[]).length>0&&<div className="mt-4 border-t border-[#e5eded] pt-3"><p className="text-xs font-bold uppercase tracking-wider text-[#668087]">Private attachments</p><div className="mt-2 flex flex-wrap gap-2">{(ref.uploadIds??[]).map((uploadId,index)=><button key={uploadId} className="btn-outline !px-3 !py-2 text-xs" disabled={attachmentAccess.isPending} onClick={()=>attachmentAccess.mutate({referralId:ref.id,uploadId},{onSuccess:r=>window.open(r.url,'_blank','noopener,noreferrer'),onError:adminError})}>Open attachment {index+1}</button>)}</div></div>}
      </article>)}</div>}</section>}
      {tab==='schedule'&&<div className="mt-6 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><section className="soft-card rounded-2xl p-5 sm:p-7"><p className="eyebrow">Published clinic schedule</p><h2 className="mt-2 text-xl font-bold text-[#21485a]">Weekly hours</h2>{schedules.isError?<ErrorPanel retry={()=>schedules.refetch()}/>:schedules.isLoading?<div className="mt-4 h-32 animate-pulse rounded-xl bg-[#e5eeee]"/>:!schedules.data?.length?<p className="mt-4 text-sm text-[#687e85]">No schedule data is available.</p>:schedules.data.map(schedule=><ScheduleEditor key={schedule.locationId} item={schedule} onSave={(weeklyHours,slotDurationMinutes)=>updateSchedule.mutate({locationId:schedule.locationId,data:{weeklyHours,slotDurationMinutes}},{onSuccess:refresh,onError:adminError})}/>)}</section>
        <section className="soft-card rounded-2xl p-5 sm:p-7"><p className="eyebrow">Date-specific availability</p><h2 className="mt-2 text-xl font-bold text-[#21485a]">Publish an override</h2><p className="mt-2 text-sm leading-6 text-[#617981]">Sunday emergency availability is closed by default. Publish specific slots here without changing recurring hours.</p><form className="mt-5 space-y-3" onSubmit={e=>{e.preventDefault();override.mutate({data:{locationId:overrideForm.locationId,date:overrideForm.date,kind:overrideForm.kind as 'extra'|'closed'|'blocked'|'emergency',slots:overrideForm.slots.split(',').map(s=>s.trim()).filter(Boolean),reason:overrideForm.reason}},{onSuccess:()=>{setMessage('Availability override published.');setOverrideForm({...overrideForm,slots:''});refresh()},onError:adminError})}}><select className="field" required value={overrideForm.locationId} onChange={e=>setOverrideForm({...overrideForm,locationId:e.target.value})}><option value="">Choose location</option>{locations.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select><input className="field" type="date" required value={overrideForm.date} onChange={e=>setOverrideForm({...overrideForm,date:e.target.value})}/><select className="field" value={overrideForm.kind} onChange={e=>setOverrideForm({...overrideForm,kind:e.target.value})}>{['extra','emergency','closed','blocked'].map(k=><option key={k}>{k}</option>)}</select><input className="field" required placeholder="Slot times, comma separated (HH:MM)" value={overrideForm.slots} onChange={e=>setOverrideForm({...overrideForm,slots:e.target.value})}/><input className="field" placeholder="Reason (optional)" maxLength={300} value={overrideForm.reason} onChange={e=>setOverrideForm({...overrideForm,reason:e.target.value})}/><button className="btn-primary w-full" disabled={override.isPending}>{override.isPending?'Publishing…':'Publish availability'} <Plus size={16}/></button></form>
          <div className="mt-6 border-t border-[#e1eaea] pt-4"><h3 className="text-sm font-bold text-[#315766]">Upcoming published overrides</h3>{availabilityOverrides.isError?<ErrorPanel retry={()=>availabilityOverrides.refetch()}/>:availabilityOverrides.data?.length?<ul className="mt-3 space-y-2">{availabilityOverrides.data.map(item=><li key={item.id} className="rounded-lg bg-[#f2f7f6] p-3 text-xs text-[#536d75]"><b>{item.date}</b> · {locations.find(l=>l.id===item.locationId)?.name||item.locationId} · <span className="capitalize">{item.kind}</span>{item.slots.length?` · ${item.slots.join(', ')}`:''}{item.reason?` · ${item.reason}`:''}</li>)}</ul>:<p className="mt-3 text-xs text-[#73868b]">{availabilityOverrides.isLoading?'Loading overrides…':'No upcoming overrides.'}</p>}</div>
          <details className="mt-6 border-t border-[#e0eaea] pt-4"><summary className="cursor-pointer text-sm font-bold text-[#42646e]">Cancel or reschedule an appointment</summary><p className="mt-3 text-sm leading-6 text-[#687d83]">Use appointment list actions to cancel. Rescheduling is available where a current server-published slot can be selected. Existing bookings are never changed when schedules are edited.</p></details></section></div>}
      {tab==='schedule'&&<LocationManagement locations={locations} update={(id,data)=>updateLocation.mutate({locationId:id,data},{onSuccess:()=>{void qc.invalidateQueries({queryKey:getListLocationsQueryKey()});refresh();setMessage('Clinic details updated.')},onError:adminError})}/>}
      {tab==='notifications'&&<section className="soft-card mt-6 rounded-2xl p-5 sm:p-7"><p className="eyebrow">Delivery operations</p><h2 className="mt-2 text-xl font-bold text-[#21485a]">Notification attempts</h2><p className="mt-2 text-sm text-[#617981]">Delivery status and safe retry are managed by the server.</p>{notificationQuery.isError?<ErrorPanel retry={()=>notificationQuery.refetch()}/>:!notificationQuery.data?.length?<p className="mt-5 rounded-xl bg-[#f1f6f5] p-5 text-sm text-[#6b8086]">{notificationQuery.isLoading?'Loading notification records…':'No notification records are available.'}</p>:<div className="mt-5 overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="border-b border-[#dce8e8] text-xs uppercase tracking-wider text-[#71858a]"><tr>{['Event','Recipient','Reference','Status','Attempts','Updated',''].map(x=><th className="px-3 py-3" key={x}>{x}</th>)}</tr></thead><tbody>{notificationQuery.data.map(n=><tr key={n.id} className="border-b border-[#e8eeee]"><td className="px-3 py-4">{n.event}</td><td className="px-3 py-4">{n.recipient}</td><td className="px-3 py-4">{n.entityReference}</td><td className="px-3 py-4"><span className="capitalize">{n.status.replace('_',' ')}</span>{n.lastError&&<span className="block max-w-xs text-xs text-[#975448]">{n.lastError}</span>}</td><td className="px-3 py-4">{n.attempts}</td><td className="px-3 py-4">{new Date(n.updatedAt).toLocaleString()}</td><td className="px-3 py-4">{n.status!=='sent'&&<button className="text-xs font-bold text-[#176d70] underline" disabled={retryNotification.isPending} onClick={()=>retryNotification.mutate({notificationId:n.id},{onSuccess:()=>{void notificationQuery.refetch();setMessage('Notification retry requested.')},onError:adminError})}>Retry</button>}</td></tr>)}</tbody></table></div>}</section>}
    </div>
  </main>;
}
function AdminLoading(){return <main className="min-h-[100dvh] bg-[#eff5f5] p-6"><div className="mx-auto max-w-5xl animate-pulse"><div className="h-12 w-60 rounded-xl bg-[#dce9e9]"/><div className="mt-8 h-48 rounded-2xl bg-[#e3eeee]"/><div className="mt-5 h-72 rounded-2xl bg-[#e3eeee]"/></div></main>}
function ErrorPanel({retry}:{retry:()=>void}) {return <div className="mt-5 rounded-xl border border-[#e7d2c9] bg-[#fcf5f2] p-4 text-sm text-[#794e42]">Records could not be loaded. <button className="ml-1 font-bold underline" onClick={retry}>Retry</button></div>}
function AppointmentTable({items,empty,onCancel,onReschedule}:{items:any[];empty:string;onCancel:(id:string)=>void;onReschedule?:(item:any)=>void}) {return <div className="mt-5 overflow-x-auto">{items.length?<table className="w-full min-w-[780px] text-left text-sm"><thead className="border-b border-[#dce8e8] text-xs uppercase tracking-wider text-[#71858a]"><tr>{['Time','Patient','Location','Type','Status','Source',''].map(x=><th key={x} className="px-3 py-3">{x}</th>)}</tr></thead><tbody>{items.map(item=><tr key={item.id} className="border-b border-[#e8eeee]"><td className="px-3 py-4 font-semibold text-[#244b5b]">{item.date} · {item.time}</td><td className="px-3 py-4"><b>{item.patientName}</b><span className="block text-xs text-[#71858a]">{item.phone}</span></td><td className="px-3 py-4">{item.locationName}</td><td className="px-3 py-4">{item.appointmentType}</td><td className="px-3 py-4"><span className="rounded-full bg-[#e7f1ef] px-2.5 py-1 text-xs font-bold capitalize text-[#31746f]">{item.status}</span></td><td className="px-3 py-4 capitalize">{item.source}</td><td className="px-3 py-4"><div className="flex gap-2">{item.status!=='cancelled'&&<><button className="text-xs font-bold text-[#176d70] underline" onClick={()=>onReschedule?.(item)}>Reschedule</button><button className="text-xs font-bold text-[#9b5147] underline" onClick={()=>onCancel(item.id)}>Cancel</button></>}</div></td></tr>)}</tbody></table>:<p className="rounded-xl bg-[#f1f6f5] p-5 text-sm text-[#6b8086]">{empty}</p>}</div>}
function PhoneBooking({locations,form,set,submit,pending}:{locations:ClinicLocation[];form:{locationId:string;date:string;slotId:string;patientName:string;phone:string;email:string;appointmentType:string;notes:string;internalNotes:string};set:(v:any)=>void;submit:(v:any)=>void;pending:boolean}) {
  const params=useMemo(()=>({locationId:form.locationId,date:form.date}),[form.locationId,form.date]);const avail=useGetAvailability(params,{query:{enabled:!!form.locationId&&!!form.date,queryKey:getGetAvailabilityQueryKey(params)}});
  return <form className="soft-card rounded-2xl p-5 sm:p-7" onSubmit={e=>{e.preventDefault();submit({...form,email:form.email||null})}}><p className="eyebrow">Phone booking</p><h2 className="mt-2 text-xl font-bold text-[#21485a]">Reserve a time by phone</h2><p className="mt-2 text-sm leading-6 text-[#657a80]">Uses the same live slot availability as online booking.</p><div className="mt-5 space-y-3"><select className="field" required value={form.locationId} onChange={e=>set({...form,locationId:e.target.value,slotId:''})}><option value="">Choose clinic</option>{locations.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select><input className="field" type="date" required value={form.date} onChange={e=>set({...form,date:e.target.value,slotId:''})}/><select className="field" required value={form.slotId} onChange={e=>set({...form,slotId:e.target.value})}><option value="">Choose a published time</option>{avail.data?.slots.filter(s=>s.available).map(s=><option key={s.id} value={s.id}>{s.label}{s.emergency?' · Emergency':''}</option>)}</select>
    <input className="field" required minLength={2} placeholder="Patient name" value={form.patientName} onChange={e=>set({...form,patientName:e.target.value})}/><input className="field" required minLength={8} placeholder="Phone" value={form.phone} onChange={e=>set({...form,phone:e.target.value})}/><input className="field" type="email" placeholder="Email (optional)" value={form.email} onChange={e=>set({...form,email:e.target.value})}/><input className="field" required minLength={2} placeholder="Appointment type" value={form.appointmentType} onChange={e=>set({...form,appointmentType:e.target.value})}/><textarea className="field" placeholder="Internal notes (optional)" value={form.internalNotes} onChange={e=>set({...form,internalNotes:e.target.value})}/><button className="btn-primary w-full" disabled={pending||!form.slotId}>{pending?'Reserving…':'Reserve phone appointment'}</button></div></form>;
}
function ScheduleEditor({item,onSave}:{item:any;onSave:(hours:any[],duration:number)=>void}) {
  const [duration,setDuration]=useState(item.slotDurationMinutes);const [hours,setHours]=useState(item.weeklyHours.map((h:any)=>({...h})));
  return <details className="mt-4 rounded-xl border border-[#dce8e8] bg-white p-4"><summary className="cursor-pointer font-bold text-[#315766]">{item.locationName} <span className="ml-2 text-xs font-normal text-[#75898e]">{item.slotDurationMinutes} min slots</span></summary><div className="mt-4 space-y-3">{hours.map((h:any,i:number)=><div key={h.day} className="grid grid-cols-[1fr_1fr_1fr] items-center gap-2 text-xs"><span className="font-semibold">{['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][h.day]}</span><input className="field !px-2 !py-2" type="time" value={h.opensAt} onChange={e=>setHours(hours.map((x:any,j:number)=>j===i?{...x,opensAt:e.target.value}:x))}/><input className="field !px-2 !py-2" type="time" value={h.closesAt} onChange={e=>setHours(hours.map((x:any,j:number)=>j===i?{...x,closesAt:e.target.value}:x))}/></div>)}</div><label className="mt-4 block text-sm font-semibold">Slot duration (minutes)<input className="field mt-1" type="number" min={15} max={240} value={duration} onChange={e=>setDuration(Number(e.target.value))}/></label><button className="btn-primary mt-4 w-full !py-2.5 text-sm" onClick={()=>onSave(hours,duration)}>Save schedule</button></details>;
}
function LocationManagement({locations,update}:{locations:ClinicLocation[];update:(id:string,data:{name:string;clinicName:string;address:string;mapsUrl:string;phone:string|null})=>void}) {
  return <section className="soft-card mt-5 rounded-2xl p-5 sm:p-7"><p className="eyebrow">Practice information</p><h2 className="mt-2 text-xl font-bold text-[#21485a]">Clinic details</h2><p className="mt-2 text-sm text-[#657b81]">Update location contact and directions. Weekly hours are managed separately above.</p>
    <div className="mt-4 grid gap-3 md:grid-cols-2">{locations.map(location=><details className="rounded-xl border border-[#dce8e8] bg-white p-4" key={location.id}><summary className="cursor-pointer font-bold text-[#315766]">{location.name}</summary><form className="mt-4 space-y-3" onSubmit={e=>{e.preventDefault();const data=new FormData(e.currentTarget);update(location.id,{name:String(data.get('name')),clinicName:String(data.get('clinicName')),address:String(data.get('address')),mapsUrl:String(data.get('mapsUrl')),phone:String(data.get('phone')||'')||null})}}>
      <label className="block text-xs font-semibold">Location name<input name="name" required minLength={2} className="field mt-1" defaultValue={location.name}/></label>
      <label className="block text-xs font-semibold">Clinic name<input name="clinicName" required minLength={2} className="field mt-1" defaultValue={location.clinicName}/></label>
      <label className="block text-xs font-semibold">Address<textarea name="address" required minLength={8} className="field mt-1" defaultValue={location.address}/></label>
      <label className="block text-xs font-semibold">Maps URL<input name="mapsUrl" type="url" required className="field mt-1" defaultValue={location.mapsUrl}/></label>
      <label className="block text-xs font-semibold">Phone<input name="phone" type="tel" className="field mt-1" defaultValue={location.phone||''}/></label>
      <button className="btn-primary w-full !py-2.5 text-sm">Save clinic details</button>
    </form></details>)}</div>
  </section>;
}

function Router() {
  const [location]=useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={HomePage}/><Route path="/refer-a-patient" component={ReferralPage}/><Route path="/admin/login" component={AdminLogin}/><Route path="/admin" component={AdminDashboard}/><Route component={NotFound}/></Switch></ErrorBoundary>;
}
function App() {return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><Router/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>;}
export default App;
